{
  "sql": "SELECT m.chembl_id AS molecule_chembl_id, m.pref_name AS molecule_name, m.max_phase, m.molecule_type, cs.canonical_smiles FROM molecule_dictionary m JOIN compound_records cr ON m.molregno = cr.molregno JOIN docs d ON cr.doc_id = d.doc_id LEFT JOIN compound_structures cs ON m.molregno = cs.molregno WHERE d.chembl_id = 'CHEMBL4004822' ORDER BY molecule_chembl_id"
}
